          "sampleValue": "♪"
        },
        "name": {
          "type": "string",
          "description": "新闻歌单名称",
          "sampleValue": "新闻"
        },
        "selected": {
          "type": "boolean",
          "description": "新闻歌单是否被勾选",
          "sampleValue": false
        },
        "value": {
          "type": "string",
          "description": "新闻歌单勾选值",
          "sampleValue": "news"
        }
      }
    },
    "alert": {
      "message": {
        "type": "string",
        "description": "耳机连接状态告警文案",
        "sampleValue": "耳机连接已断开"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转音乐 App 的动作入口文案",
        "sampleValue": "播放通勤歌单"
      },
      "hint": {
        "type": "string",
        "description": "动作区辅助说明",
        "sampleValue": "打开音乐 App"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_music.png",
      "description": "音乐图标，适合用于当前播放歌曲的信息识别。"
    },
    {
      "src": "resources/base/media/icon_earphone.png",
      "description": "耳机图标，适合用于耳机连接或断开状态提示。"
    }
  ]
}

